import { Text } from "@xco-agency/corex-ui";
import type { ChangeIndicatorPropsType } from "../types";

/**
 * Shopify's change figure next to a value: "↗ 34%" in green, "↘ 12%" in
 * red, "→ 0%" when flat, and nothing without a previous period.
 */
export function ChangeIndicator({ pct, label }: ChangeIndicatorPropsType) {
  if (pct == null) return null;
  const up = pct > 0;
  const flat = pct === 0;
  return (
    <Text
      as="span"
      variant="bodySm"
      fontWeight="semibold"
      color={flat ? "subdued" : up ? "success" : "critical"}
      aria-label={label}
    >
      {`${flat ? "→" : up ? "↗" : "↘"} ${Math.abs(pct)}%`}
    </Text>
  );
}

import { BlockStack, Card, InlineStack, Text } from "@xco-agency/corex-ui";
import type { ChartCardPropsType } from "../types";
import { ChangeIndicator } from "./ChangeIndicator";

/**
 * Shopify's analytics card: a Corex `Card`, so the title (`heading`), its
 * definition (`tooltip`) and header `actions` are the Card's own, then the
 * headline value with its change, then the chart.
 */
export function ChartCard({
  value,
  change,
  changeLabel,
  children,
  ...card
}: ChartCardPropsType) {
  return (
    <Card {...card}>
      <BlockStack gap="base">
        {value != null && (
          <InlineStack gap="small-200" alignItems="center">
            <Text as="p" variant="headingLg">
              {value}
            </Text>
            <ChangeIndicator pct={change ?? null} label={changeLabel} />
          </InlineStack>
        )}
        {children}
      </BlockStack>
    </Card>
  );
}

import type { CardPropsType } from "@xco-agency/corex-ui";

export type PeriodRangeType = {
  /** First day of the previous period (YYYY-MM-DD). */
  previousFrom: string;
  /** First day of the current period (YYYY-MM-DD). */
  currentFrom: string;
  /** Last day of the current period (YYYY-MM-DD). */
  to: string;
};

export type PeriodSeriesType = {
  /** The current period's days, oldest first. */
  dates: string[];
  current: number[];
  /** The previous period's days, as many as the current one's. */
  previousDates: string[];
  /** Null when the previous period has no data at all. */
  previous: number[] | null;
};

export type ChangeIndicatorPropsType = {
  /** Percent change; nothing renders for null. */
  pct: number | null;
  /** Read out instead of the arrow, e.g. "Up 34% from the previous period". */
  label?: string;
};

/** A Corex `Card`: `heading`, `tooltip`, `actions` and the rest are the Card's own props. */
export type ChartCardPropsType = CardPropsType & {
  /** The headline figure, as shown. */
  value?: string;
  /** Percent change next to the value. */
  change?: number | null;
  /** Accessible label for the change. */
  changeLabel?: string;
};

import type { PeriodRangeType, PeriodSeriesType } from "./types";

/**
 * Change from `previous` to `current` in percent, one decimal; null when
 * there is no previous value to compare with (never invented).
 */
export function percentChange(
  current: number,
  previous: number | null | undefined,
): number | null {
  if (previous == null || !(previous > 0)) return null;
  return Math.round(((current - previous) / previous) * 1000) / 10;
}

/** Days from `from` to `to` inclusive, as YYYY-MM-DD (UTC), bounded to 800. */
export function dayRange(from: string, to: string): string[] {
  const out: string[] = [];
  const cursor = new Date(`${from.slice(0, 10)}T00:00:00Z`);
  const last = new Date(`${to.slice(0, 10)}T00:00:00Z`);
  if (Number.isNaN(cursor.getTime()) || Number.isNaN(last.getTime())) {
    return out;
  }
  for (let i = 0; cursor <= last && i < 800; i += 1) {
    out.push(cursor.toISOString().slice(0, 10));
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  return out;
}

/**
 * Splits daily rows into the current period and the equally long one
 * before it, each day filled (no row = 0). The previous period is null
 * when it holds no rows at all, so no flat comparison line is drawn at 0.
 */
export function periodSeries<T extends { date: string }>(
  rows: T[],
  range: PeriodRangeType,
  pick: (row: T) => number,
): PeriodSeriesType {
  const byDate = new Map<string, number>();
  for (const row of rows) {
    const key = String(row.date).slice(0, 10);
    byDate.set(key, (byDate.get(key) ?? 0) + (Number(pick(row)) || 0));
  }
  const dates = dayRange(range.currentFrom, range.to);
  const previousAll = dayRange(range.previousFrom, range.currentFrom).slice(0, -1);
  // Align the previous period to the current one's length, ending the day
  // before the current period starts.
  const previousDates = previousAll.slice(-dates.length);
  const current = dates.map((d) => byDate.get(d) ?? 0);
  const previousValues = previousDates.map((d) => byDate.get(d) ?? 0);
  const hasPrevious =
    previousDates.length === dates.length && previousDates.some((d) => byDate.has(d));
  return {
    dates,
    current,
    previousDates,
    previous: hasPrevious ? previousValues : null,
  };
}

export const sum = (values: number[]): number =>
  values.reduce((total, v) => total + (Number(v) || 0), 0);
